package main

import (
	"flag"
	"fmt"
	"image"
	"image/color"
	"image/gif"
	"image/jpeg"
	"image/png"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

type Options struct {
	Color        bool
	ColorBg      bool
	Dimensions   string
	Width        int
	Height       int
	Map          string
	Braille      bool
	Threshold    int
	Dither       bool
	Grayscale    bool
	Complex      bool
	Full         bool
	Negative     bool
	FlipX        bool
	FlipY        bool
	SaveImg      string
	SaveTxt      string
	SaveGif      string
	SaveBg       string
	Font         string
	FontColor    string
	OnlySave     bool
	Formats      bool
	Help         bool
	Version      bool
	InputPaths   []string
}

// ASCII art character maps from darkest to lightest
const (
	SimpleMap   = " .:-=+*#%@"
	ComplexMap  = " `.-':_,^=;><+!rc*/z?sxnuvhjwqpdbkO*&#MB%@$"
	DefaultMap  = " .:-=+*#%@"
)

func parseArgs() (*Options, []string, error) {
	opts := &Options{
		Threshold: 128,
	}

	// Parse flags
	fs := flag.NewFlagSet("ascii-image-converter", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)

	fs.BoolVar(&opts.Color, "C", false, "")
	fs.BoolVar(&opts.Color, "color", false, "")
	fs.BoolVar(&opts.ColorBg, "color-bg", false, "")
	fs.StringVar(&opts.Dimensions, "d", "", "")
	fs.StringVar(&opts.Dimensions, "dimensions", "", "")
	fs.IntVar(&opts.Width, "W", 0, "")
	fs.IntVar(&opts.Width, "width", 0, "")
	fs.IntVar(&opts.Height, "H", 0, "")
	fs.IntVar(&opts.Height, "height", 0, "")
	fs.StringVar(&opts.Map, "m", "", "")
	fs.StringVar(&opts.Map, "map", "", "")
	fs.BoolVar(&opts.Braille, "b", false, "")
	fs.BoolVar(&opts.Braille, "braille", false, "")
	fs.IntVar(&opts.Threshold, "threshold", 128, "")
	fs.BoolVar(&opts.Dither, "dither", false, "")
	fs.BoolVar(&opts.Grayscale, "g", false, "")
	fs.BoolVar(&opts.Grayscale, "grayscale", false, "")
	fs.BoolVar(&opts.Complex, "c", false, "")
	fs.BoolVar(&opts.Complex, "complex", false, "")
	fs.BoolVar(&opts.Full, "f", false, "")
	fs.BoolVar(&opts.Full, "full", false, "")
	fs.BoolVar(&opts.Negative, "n", false, "")
	fs.BoolVar(&opts.Negative, "negative", false, "")
	fs.BoolVar(&opts.FlipX, "x", false, "")
	fs.BoolVar(&opts.FlipX, "flipX", false, "")
	fs.BoolVar(&opts.FlipY, "y", false, "")
	fs.BoolVar(&opts.FlipY, "flipY", false, "")
	fs.StringVar(&opts.SaveImg, "s", "", "")
	fs.StringVar(&opts.SaveImg, "save-img", "", "")
	fs.StringVar(&opts.SaveTxt, "save-txt", "", "")
	fs.StringVar(&opts.SaveGif, "save-gif", "", "")
	fs.StringVar(&opts.SaveBg, "save-bg", "", "")
	fs.StringVar(&opts.Font, "font", "", "")
	fs.StringVar(&opts.FontColor, "font-color", "", "")
	fs.BoolVar(&opts.OnlySave, "only-save", false, "")
	fs.BoolVar(&opts.Formats, "formats", false, "")
	fs.BoolVar(&opts.Help, "h", false, "")
	fs.BoolVar(&opts.Help, "help", false, "")
	fs.BoolVar(&opts.Version, "v", false, "")
	fs.BoolVar(&opts.Version, "version", false, "")

	fs.Usage = func() {}

	err := fs.Parse(os.Args[1:])
	if err != nil {
		return nil, nil, err
	}

	opts.InputPaths = fs.Args()

	return opts, opts.InputPaths, nil
}

func printHelp() {
	fmt.Println(`This tool converts images into ascii art and prints them on the terminal.
Further configuration can be managed with flags.

Usage:
  ascii-image-converter [image paths/urls or piped stdin] [flags]

Flags:
  -C, --color             Display ascii art with original colors
                          If 24-bit colors aren't supported, uses 8-bit
                          (Inverts with --negative flag)
                          (Overrides --grayscale and --font-color flags)

      --color-bg          If some color flag is passed, use that color
                          on character background instead of foreground
                          (Inverts with --negative flag)
                          (Only applicable for terminal display)

  -d, --dimensions ints   Set width and height for ascii art in CHARACTER length
                          e.g. -d 60,30 (defaults to terminal height)
                          (Overrides --width and --height flags)

  -W, --width int         Set width for ascii art in CHARACTER length
                          Height is kept to aspect ratio
                          e.g. -W 60

  -H, --height int        Set height for ascii art in CHARACTER length
                          Width is kept to aspect ratio
                          e.g. -H 60

  -m, --map string        Give custom ascii characters to map against
                          Ordered from darkest to lightest
                          e.g. -m " .-+#@" (Quotation marks excluded from map)
                          (Overrides --complex flag)

  -b, --braille           Use braille characters instead of ascii
                          Terminal must support braille patterns properly
                          (Overrides --complex and --map flags)

      --threshold int     Threshold for braille art
                          Value between 0-255 is accepted
                          e.g. --threshold 170
                          (Defaults to 128)

      --dither            Apply dithering on image for braille
                          art conversion
                          (Only applicable with --braille flag)
                          (Negates --threshold flag)

  -g, --grayscale         Display grayscale ascii art
                          (Inverts with --negative flag)
                          (Overrides --font-color flag)

  -c, --complex           Display ascii characters in a larger range
                          May result in higher quality

  -f, --full              Use largest dimensions for ascii art
                          that fill the terminal width
                          (Overrides --dimensions, --width and --height flags)

  -n, --negative          Display ascii art in negative colors

  -x, --flipX             Flip ascii art horizontally

  -y, --flipY             Flip ascii art vertically

  -s, --save-img string   Save ascii art as a .png file
                          Format: <image-name>-ascii-art.png
                          Image will be saved in passed path
                          (pass . for current directory)

      --save-txt string   Save ascii art as a .txt file
                          Format: <image-name>-ascii-art.txt
                          File will be saved in passed path
                          (pass . for current directory)

      --save-gif string   If input is a gif, save it as a .gif file
                          Format: <gif-name>-ascii-art.gif
                          Gif will be saved in passed path
                          (pass . for current directory)

      --save-bg ints      Set background color for --save-img
                          and --save-gif flags
                          Pass an RGBA value
                          e.g. --save-bg 255,255,255,100
                          (Defaults to 0,0,0,100)

      --font string       Set font for --save-img and --save-gif flags
                          Pass file path to font .ttf file
                          e.g. --font ./RobotoMono-Regular.ttf
                          (Defaults to Hack-Regular for ascii and
                           DejaVuSans-Oblique for braille)

      --font-color ints   Set font color for terminal as well as
                          --save-img and --save-gif flags
                          Pass an RGB value
                          e.g. --font-color 0,0,0
                          (Defaults to 255,255,255)

      --only-save         Don't print ascii art on terminal
                          if some saving flag is passed

      --formats           Display supported input formats

  -h, --help              Help for ascii-image-converter

  -v, --version           Version for ascii-image-converter

Copyright © 2021 Zoraiz Hassan <hzoraiz8@gmail.com>
Distributed under the Apache License Version 2.0 (Apache-2.0)
For further details, visit https://github.com/TheZoraiz/ascii-image-converter`)
}

func printFormats() {
	fmt.Println(`Supported input formats:

JPEG/JPG
PNG
WEBP
BMP
TIFF/TIF
GIF

`)
}

// convertImageToASCII converts an image to ASCII art
func convertImageToASCII(img image.Image, opts *Options) string {
	// Get dimensions
	bounds := img.Bounds()
	imgWidth := bounds.Dx()
	imgHeight := bounds.Dy()

	// Calculate ASCII output dimensions
	outputWidth := opts.Width
	outputHeight := opts.Height

	if opts.Dimensions != "" {
		parts := strings.Split(opts.Dimensions, ",")
		if len(parts) == 2 {
			w, _ := strconv.Atoi(strings.TrimSpace(parts[0]))
			h, _ := strconv.Atoi(strings.TrimSpace(parts[1]))
			outputWidth = w
			outputHeight = h
		}
	}

	// Default dimensions
	if outputWidth == 0 && outputHeight == 0 {
		outputWidth = 80
		outputHeight = 24
	} else if outputWidth == 0 {
		outputWidth = (imgWidth * outputHeight) / imgHeight
	} else if outputHeight == 0 {
		outputHeight = (imgHeight * outputWidth) / imgWidth
	}

	// Accumulate the ASCII art
	result := ""

	// Get the character map
	charMap := DefaultMap
	if opts.Map != "" {
		charMap = opts.Map
	} else if opts.Complex {
		charMap = ComplexMap
	}

	// Process each row
	for y := 0; y < outputHeight; y++ {
		for x := 0; x < outputWidth; x++ {
			// Get corresponding pixel in original image
			srcX := (x * imgWidth) / outputWidth
			srcY := (y * imgHeight) / outputHeight

			// Get pixel color
			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)

			// Convert to grayscale
			r, g, b, _ := c.RGBA()
			gray := (299*r + 587*g + 114*b) / 1000 / 256

			// Map to ASCII character
			if gray > 255 {
				gray = 255
			}
			charIndex := int(gray) * len(charMap) / 256
			if charIndex >= len(charMap) {
				charIndex = len(charMap) - 1
			}

			result += string(charMap[charIndex])
		}
		result += "\n"
	}

	return result
}

// loadImage loads an image from a file
func loadImage(filePath string) (image.Image, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	// Try to detect format from extension or content
	ext := strings.ToLower(filepath.Ext(filePath))

	switch ext {
	case ".png":
		return png.Decode(file)
	case ".jpg", ".jpeg":
		return jpeg.Decode(file)
	case ".gif":
		// For GIF, just get the first frame
		g, err := gif.DecodeAll(file)
		if err != nil {
			return nil, err
		}
		if len(g.Image) > 0 {
			return g.Image[0], nil
		}
		return nil, fmt.Errorf("empty GIF")
	default:
		return nil, fmt.Errorf("unsupported format: %s", ext)
	}
}

// processImage processes a single image file
func processImage(filePath string, opts *Options) error {
	img, err := loadImage(filePath)
	if err != nil {
		return fmt.Errorf("can't decode %s: %v", filePath, err)
	}

	// Convert to ASCII
	ascii := convertImageToASCII(img, opts)

	// Output
	if !opts.OnlySave {
		fmt.Print(ascii)
	}

	// Save if requested
	if opts.SaveTxt != "" {
		baseName := strings.TrimSuffix(filepath.Base(filePath), filepath.Ext(filePath))
		outPath := filepath.Join(opts.SaveTxt, baseName+"-ascii-art.txt")
		err := os.WriteFile(outPath, []byte(ascii), 0644)
		if err != nil {
			return fmt.Errorf("error saving text: %v", err)
		}
	}

	return nil
}

func main() {
	opts, inputPaths, err := parseArgs()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error parsing arguments: %v\n", err)
		os.Exit(1)
	}

	if opts.Version {
		fmt.Println("v1.13.1")
		return
	}

	if opts.Help {
		printHelp()
		return
	}

	if opts.Formats {
		printFormats()
		return
	}

	// Check for input
	if len(inputPaths) == 0 {
		fmt.Println("Error: Need at least 1 input path/url or piped input")
		fmt.Println("Use the -h flag for more info")
		os.Exit(1)
	}

	// Process each image
	for _, path := range inputPaths {
		err := processImage(path, opts)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		}
	}
}
