	if err != nil {
		return fmt.Errorf("can't decode %s: %v", filePath, err)
	}

	// Convert to ASCII
	ascii := convertImageToASCII(img, opts)

	// Output
	if !opts.OnlySave {
		fmt.Print(ascii)
	}

	// Save if requested
	if opts.SaveTxt != "" {
		baseName := strings.TrimSuffix(filepath.Base(filePath), filepath.Ext(filePath))
		outPath := filepath.Join(opts.SaveTxt, baseName+"-ascii-art.txt")
		err := os.WriteFile(outPath, []byte(ascii), 0644)
		if err != nil {
			return fmt.Errorf("error saving text: %v", err)
		}
	}

	return nil
}

func main() {
	opts, inputPaths, err := parseArgs()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error parsing arguments: %v\n", err)
		os.Exit(1)
	}

	if opts.Version {
		fmt.Println("v1.13.1")
		return
	}

	if opts.Help {
		printHelp()
		return
	}

	if opts.Formats {
		printFormats()
		return
	}

