	imgHeight := bounds.Dy()

	// Calculate ASCII output dimensions
	outputWidth := opts.Width
	outputHeight := opts.Height

	if opts.Dimensions != "" {
		parts := strings.Split(opts.Dimensions, ",")
		if len(parts) == 2 {
			w, _ := strconv.Atoi(strings.TrimSpace(parts[0]))
			h, _ := strconv.Atoi(strings.TrimSpace(parts[1]))
			outputWidth = w
			outputHeight = h
		}
	}

	// Default dimensions
	if outputWidth == 0 && outputHeight == 0 {
		outputWidth = 80
		outputHeight = 24
	} else if outputWidth == 0 {
		if imgHeight > 0 {
			outputWidth = (imgWidth * outputHeight) / imgHeight
		}
	} else if outputHeight == 0 {
		if imgWidth > 0 {
			outputHeight = (imgHeight * outputWidth) / imgWidth
		}
	}

	// Accumulate the ASCII art
	result := ""

	// Get the character map
	charMap := DefaultMap
	if opts.Map != "" {
		charMap = opts.Map
	} else if opts.Complex {
		charMap = ComplexMap
	}

	// Process each row
	for y := 0; y < outputHeight; y++ {
		for x := 0; x < outputWidth; x++ {
			// Get corresponding pixel in original image
			srcX := (x * imgWidth) / outputWidth
			srcY := (y * imgHeight) / outputHeight

			if srcX >= imgWidth {
				srcX = imgWidth - 1
			}
			if srcY >= imgHeight {
				srcY = imgHeight - 1
			}

			// Get pixel color
			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)

			// Convert to grayscale
			r, g, b, _ := c.RGBA()
			// RGBA returns 16-bit values, convert to 8-bit
			gray := (299*r + 587*g + 114*b) / 1000
			gray = gray >> 8  // Convert from 16-bit to 8-bit

			// Apply negative if requested
			if opts.Negative {
				gray = 255 - gray
			}

			// Map to ASCII character
			if gray > 255 {
				gray = 255
			}
			charIndex := int(gray) * len(charMap) / 256
			if charIndex >= len(charMap) {
				charIndex = len(charMap) - 1
			}

			result += string(charMap[charIndex])
		}
		result += "\n"
	}

	return result
}

