		outPath := filepath.Join(opts.SaveTxt, baseName+"-ascii-art.txt")
		err := os.WriteFile(outPath, []byte(ascii), 0644)
		if err != nil {
			return fmt.Errorf("error saving text: %v", err)
		}
	}

	return nil
}

