			if srcX >= imgWidth {
				srcX = imgWidth - 1
			}
			if srcY >= imgHeight {
				srcY = imgHeight - 1
			}

			// Get pixel color
			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)

			// Convert to grayscale
			r, g, b, _ := c.RGBA()
