// Pixel contains RGBA color information
type Pixel struct {
	R, G, B, A uint8
}

// convertImageToASCII converts an image to ASCII art
func convertImageToASCII(img image.Image, opts *Options) []string {
	// Get dimensions
	bounds := img.Bounds()
	imgWidth := bounds.Dx()
	imgHeight := bounds.Dy()

	// Calculate ASCII output dimensions
	outputWidth := opts.Width
	outputHeight := opts.Height

	if opts.Dimensions != "" {
		parts := strings.Split(opts.Dimensions, ",")
		if len(parts) == 2 {
			w, _ := strconv.Atoi(strings.TrimSpace(parts[0]))
			h, _ := strconv.Atoi(strings.TrimSpace(parts[1]))
			outputWidth = w
			outputHeight = h
		}
	}

	// Default dimensions
	if outputWidth == 0 && outputHeight == 0 {
		outputWidth = 80
		outputHeight = 24
	} else if outputWidth == 0 {
		if imgHeight > 0 {
			outputWidth = (imgWidth * outputHeight) / imgHeight
		}
	} else if outputHeight == 0 {
		if imgWidth > 0 {
			outputHeight = (imgHeight * outputWidth) / imgWidth
		}
	}

	// Get the character map
	charMap := DefaultMap
	if opts.Map != "" {
		charMap = opts.Map
	} else if opts.Complex {
		charMap = ComplexMap
	}

	// Build result line by line
	lines := make([]string, outputHeight)
	var pixels [][]Pixel
	if opts.Color {
		pixels = make([][]Pixel, outputHeight)
		for i := range pixels {
			pixels[i] = make([]Pixel, outputWidth)
		}
	}

	// Process each row
	for y := 0; y < outputHeight; y++ {
		line := ""
		for x := 0; x < outputWidth; x++ {
			// Get corresponding pixel in original image
			srcX := (x * imgWidth) / outputWidth
			srcY := (y * imgHeight) / outputHeight

			if srcX >= imgWidth {
				srcX = imgWidth - 1
			}
			if srcY >= imgHeight {
				srcY = imgHeight - 1
			}

			// Get pixel color
			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)

			// Convert to RGBA
			r, g, b, a := c.RGBA()
			// RGBA returns 16-bit values, convert to 8-bit
			r8 := uint8(r >> 8)
			g8 := uint8(g >> 8)
			b8 := uint8(b >> 8)
			a8 := uint8(a >> 8)

			// Store color for later use if needed
			if opts.Color {
				pixels[y][x] = Pixel{r8, g8, b8, a8}
			}

			// Convert to grayscale
			gray := (299*int(r8) + 587*int(g8) + 114*int(b8)) / 1000

			// Apply negative if requested
			if opts.Negative {
				gray = 255 - gray
			}

			// Map to ASCII character
			if gray > 255 {
				gray = 255
			}
			if gray < 0 {
				gray = 0
			}
			charIndex := gray * len(charMap) / 256
			if charIndex >= len(charMap) {
				charIndex = len(charMap) - 1
			}

			line += string(charMap[charIndex])
		}
		lines[y] = line
	}

	// Apply flips if requested
	if opts.FlipX {
		for i, line := range lines {
			// Reverse the line
			runes := []rune(line)
			for j, k := 0, len(runes)-1; j < k; j, k = j+1, k-1 {
				runes[j], runes[k] = runes[k], runes[j]
			}
			lines[i] = string(runes)
		}
		if opts.Color {
			for i := 0; i < len(pixels); i++ {
				for j, k := 0, len(pixels[i])-1; j < k; j, k = j+1, k-1 {
					pixels[i][j], pixels[i][k] = pixels[i][k], pixels[i][j]
				}
			}
		}
	}

	if opts.FlipY {
		// Reverse the order of lines
		for i, j := 0, len(lines)-1; i < j; i, j = i+1, j-1 {
			lines[i], lines[j] = lines[j], lines[i]
		}
		if opts.Color {
			for i, j := 0, len(pixels)-1; i < j; i, j = i+1, j-1 {
				pixels[i], pixels[j] = pixels[j], pixels[i]
			}
		}
	}

	// Apply color if requested
	if opts.Color && len(pixels) > 0 {
		coloredLines := make([]string, len(lines))
		for y, line := range lines {
			coloredLine := ""
			for x := 0; x < len(line); x++ {
				p := pixels[y][x]
				char := string(line[x])

				// Invert color for negative
				r, g, b := p.R, p.G, p.B
				if opts.Negative {
					r = 255 - r
					g = 255 - g
					b = 255 - b
				}

				if opts.ColorBg {
					// Apply as background color
					coloredLine += fmt.Sprintf("\033[48;2;%d;%d;%dm%s\033[0m", r, g, b, char)
				} else {
					// Apply as foreground color
					coloredLine += fmt.Sprintf("\033[38;2;%d;%d;%dm%s\033[0m", r, g, b, char)
				}
			}
			coloredLines[y] = coloredLine
		}
		return coloredLines
	}

	return lines
}

// loadImage loads an image from a file
func loadImage(filePath string) (image.Image, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	// Try to detect format from extension or content
	ext := strings.ToLower(filepath.Ext(filePath))

	switch ext {
	case ".png":
		return png.Decode(file)
	case ".jpg", ".jpeg":
		return jpeg.Decode(file)
	case ".gif":
		// For GIF, just get the first frame
		g, err := gif.DecodeAll(file)
		if err != nil {
			return nil, err
		}
		if len(g.Image) > 0 {
			return g.Image[0], nil
		}
		return nil, fmt.Errorf("empty GIF")
	default:
		return nil, fmt.Errorf("unknown format")
	}
}

// processImage processes a single image file
func processImage(filePath string, opts *Options) error {
	fmt.Fprintf(os.Stderr, "Generating ascii art... 0%%\n")

	img, err := loadImage(filePath)
	if err != nil {
		return fmt.Errorf("can't decode %s: %s", filePath, err.Error())
	}

	// Convert to ASCII
	lines := convertImageToASCII(img, opts)
	ascii := strings.Join(lines, "\n") + "\n"

	// Output
	if !opts.OnlySave {
		fmt.Print(ascii)
	}

	// Save if requested
	if opts.SaveTxt != "" {
		baseName := strings.TrimSuffix(filepath.Base(filePath), filepath.Ext(filePath))
		outPath := filepath.Join(opts.SaveTxt, baseName+"-ascii-art.txt")
		err := os.WriteFile(outPath, []byte(ascii), 0644)
		if err != nil {
			return fmt.Errorf("error saving text: %v", err)
		}
	}

	return nil
}

func main() {
	opts, inputPaths, err := parseArgs()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error parsing arguments: %v\n", err)
		os.Exit(1)
	}

	if opts.Version {
		fmt.Println("v1.13.1")
		return
	}

	if opts.Help {
		printHelp()
		return
	}

	if opts.Formats {
		printFormats()
		return
	}

	// Check for input
	if len(inputPaths) == 0 {
		fmt.Println("Error: Need at least 1 input path/url or piped input")
		fmt.Println("Use the -h flag for more info")
		os.Exit(1)
	}

	// Process each image
	for _, path := range inputPaths {
		err := processImage(path, opts)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
		}
	}
}
